/bin/bash -lc "python - <<'PY'
import json
from pathlib import Path
for p in [Path('graphify-out/graph.json'), Path('graphify-out/2026-08-09/graph.json')]:
    try:
        d=json.loads(p.read_text())
        print(p, len(d.get('nodes',[])), len(d.get('edges',[])))
        names={n.get('name') for n in d.get('nodes',[])}
        print('document names', sorted(n for n in names if n and ('Document' in n or 'persist_document' in n or 'FiscalIdentity' in n))[:30])
    except Exception as e: print(e)
PY
printf '\\n---GRAPH DIFF SUMMARY AGAINST BACKUP---\\n'; git diff --no-index --stat graphify-out/2026-08-09/graph.json graphify-out/graph.json || true"

